def find_lexicographically_smallest_permutation(N, A):
    # Apply the left shift operation to find the lexicographically smallest permutation
    min_permutation = A[:]
    for _ in range(N):
        min_permutation = min_permutation[1:] + [min_permutation[0]]
        if min_permutation < A:
            A = min_permutation[:]

    # Try to find the best two swaps to further minimize the permutation
    for i in range(N):
        for j in range(i + 1, N):
            A[i], A[j] = A[j], A[i]
            if A < min_permutation:
                min_permutation = A[:]
            A[i], A[j] = A[j], A[i]

    return min_permutation

def main():
    T = int(input())
    results = []
    for _ in range(T):
        N = int(input())
        A = list(map(int, input().split()))
        result = find_lexicographically_smallest_permutation(N, A)
        results.append(' '.join(map(str, result)))
    print('\n'.join(results))

if __name__ == "__main__":
